THOUGHT: Now I understand the structure of `interval16`. It has:
- `start`: the starting value of the interval
- `length`: the length minus 1 (so the actual length is `length + 1`)

This means:
- The last element of the interval is `start + length`
- So `a.last()` would return `a.start + a.length`

Let me now create a simple reproduction script to verify the issue described in the PR:

```bash
cat <<'EOF' > reproduce_issue.go
package main

import (
    "fmt"
    "os"
    "github.com/RoaringBitmap/roaring/v2/roaring64"
)

func main() {
    // Create a bitmap and add some values that should form adjacent intervals
    rb := roaring64.New()

    // Add values that create adjacent intervals: [0,5] and [6,10]
    for i := uint64(0); i <= 5; i++ {
        rb.Add(i)
    }
    for i := uint64(6); i <= 10; i++ {
        rb.Add(i)
    }

    // These should be merged into a single interval [0,10]
    // but the merging logic is broken
    fmt.Printf("Cardinality: %d\n", rb.GetCardinality())
    fmt.Printf("Contains all values 0-10: %t\n", rb.ContainsRange(0, 11))

    // The issue becomes apparent when doing operations that trigger merging
    rb2 := roaring64.New()
    rb2.Add(0)
    rb2.Add(11)

    result := roaring64.Or(rb, rb2)
    fmt.Printf("Union result cardinality: %d\n", result.GetCardinality())

    // Additional debugging
    fmt.Printf("rb contains 0-10: %t\n", rb.ContainsRange(0, 11))
    fmt.Printf("result contains 0-11: %t\n", result.ContainsRange(0, 12))
}
EOF
```

